51	const PROCESSING_FEE = 5;
52	const FIRST_INSURANCE_SURCHARGE_RATE = 1 / 10;
53	const BASE_PREMIUMS: Record<string, number> = {
54	  sword: 100,
55	  amulet: 60,
56	  staff: 80,
57	  potion: 40,
58	  rune: 25,
59	  moonstone: 25,
60	};
61	
62	const BLOCK_SIZE = 3;
63	const BLOCK_BASE_PREMIUM = 60;
64	
65	const countByType = (items: Item[]): Map<string, number> => {
66	  const counts = new Map<string, number>();
67	  for (const item of items) {
68	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
69	  }
70	  return counts;
71	};
72	
73	// A building block of 3 alike components is offered at a special base premium.
74	const groupBasePremium = (type: string, count: number): number =>
75	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
76	
77	const policyBasePremium = (items: Item[]): number => {
78	  let total = 0;
79	  for (const [type, count] of countByType(items)) {
80	    total += groupBasePremium(type, count);
81	  }
82	  return total;
83	};
84	
85	// Premiums round up, in the MHPCO's favour. The surcharge is added as a
86	// separate term rather than folded into a `base * 1.1` factor, which is not
87	// exact in binary floating point (100 * 1.1 === 110.00000000000001).
88	const quotePremium = (items: Item[]): number => {
89	  const base = policyBasePremium(items);
90	  return Math.ceil(base + base * FIRST_INSURANCE_SURCHARGE_RATE + PROCESSING_FEE);
91	};
92	
93	const quote = (step: QuoteStep): QuoteResult => ({
94	  premium: quotePremium(step.items),
95	});
96	
97	const runStep = (step: Step): Result => {
98	  switch (step.op) {
99	    case "quote":
100	      return quote(step);
101	    default:
102	      throw new Error(`unsupported step: ${step.op}`);
103	  }
104	};
105	
106	export const runScenario = (scenario: Scenario): ScenarioResult => ({
107	  results: scenario.steps.map(runStep),
108	});
109

